const listCustomerSubscriptionsDetailed = `-- name: ListCustomerSubscriptionsDetailed :many
SELECT
  s.id, s.user_id, s.slot, s.label, s.status, s.remnawave_user_id, s.remnawave_username, s.observed_state, s.reconciled_at, s.created_at, s.updated_at, s.closed_at,
  e.id AS entitlement_id,
  e.status AS entitlement_status,
  e.starts_at AS entitlement_starts_at,
  e.ends_at AS entitlement_ends_at,
  e.traffic_allowance_bytes,
  e.device_limit,
  e.remnawave_squad_ids,
  p.code AS plan_code,
  v.version AS plan_version
FROM subscriptions s
LEFT JOIN LATERAL (
  SELECT en.id, en.user_id, en.order_id, en.plan_version_id, en.status, en.starts_at, en.ends_at, en.traffic_allowance_bytes, en.device_limit, en.remnawave_squad_ids, en.remnawave_user_id, en.observed_state, en.reconciled_at, en.created_at, en.updated_at, en.subscription_id FROM entitlements en
  WHERE en.subscription_id = s.id AND en.status IN ('pending', 'active', 'limited', 'disabled')
  ORDER BY en.ends_at DESC
  LIMIT 1
) e ON true
LEFT JOIN plan_versions v ON v.id = e.plan_version_id
LEFT JOIN plans p ON p.id = v.plan_id
WHERE s.user_id = $1
ORDER BY s.slot
`

type ListCustomerSubscriptionsDetailedRow struct {
	Subscription          Subscription       `json:"subscription"`
	EntitlementID         pgtype.UUID        `json:"entitlement_id"`
	EntitlementStatus     string             `json:"entitlement_status"`
	EntitlementStartsAt   pgtype.Timestamptz `json:"entitlement_starts_at"`
	EntitlementEndsAt     pgtype.Timestamptz `json:"entitlement_ends_at"`
	TrafficAllowanceBytes pgtype.Int8        `json:"traffic_allowance_bytes"`
	DeviceLimit           pgtype.Int4        `json:"device_limit"`
	RemnawaveSquadIds     []pgtype.UUID      `json:"remnawave_squad_ids"`
	PlanCode              pgtype.Text        `json:"plan_code"`
	PlanVersion           pgtype.Int4        `json:"plan_version"`
}

// Every concurrent subscription with the entitlement currently governing it, so
// the panel can offer independent lifecycle actions per subscription rather
// than assuming one per customer.
//
// The entitlement columns are selected individually rather than embedded: a
// subscription that has never been provisioned has no entitlement at all, and
// an embedded struct would have to scan those nulls into non-nullable fields.
func (q *Queries) ListCustomerSubscriptionsDetailed(ctx context.Context, userID pgtype.UUID) ([]ListCustomerSubscriptionsDetailedRow, error) {
	rows, err := q.db.Query(ctx, listCustomerSubscriptionsDetailed, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCustomerSubscriptionsDetailedRow{}
	for rows.Next() {
		var i ListCustomerSubscriptionsDetailedRow
		if err := rows.Scan(
			&i.Subscription.ID,
			&i.Subscription.UserID,
			&i.Subscription.Slot,
			&i.Subscription.Label,
			&i.Subscription.Status,
			&i.Subscription.RemnawaveUserID,
			&i.Subscription.RemnawaveUsername,
			&i.Subscription.ObservedState,
			&i.Subscription.ReconciledAt,
			&i.Subscription.CreatedAt,
			&i.Subscription.UpdatedAt,
			&i.Subscription.ClosedAt,
			&i.EntitlementID,
			&i.EntitlementStatus,
			&i.EntitlementStartsAt,
			&i.EntitlementEndsAt,
			&i.TrafficAllowanceBytes,
			&i.DeviceLimit,
			&i.RemnawaveSquadIds,
			&i.PlanCode,
			&i.PlanVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

