const markWebhookEventForReplay = `-- name: MarkWebhookEventForReplay :one
UPDATE provider_webhook_events
SET status = 'received', error_code = NULL, processed_at = NULL
WHERE id = $1 AND status IN ('failed', 'ignored')
RETURNING id, provider, provider_event_id, signature_valid, body_sha256, raw_body, headers, status, error_code, received_at, processed_at, retain_until
`

// Reprocessing is replay-safe because the downstream handlers are keyed on the
// provider event identifier, so a second pass over the same body reaches the
// same terminal state instead of applying twice.
func (q *Queries) MarkWebhookEventForReplay(ctx context.Context, eventID pgtype.UUID) (ProviderWebhookEvent, error) {
	row := q.db.QueryRow(ctx, markWebhookEventForReplay, eventID)
	var i ProviderWebhookEvent
	err := row.Scan(
		&i.ID,
		&i.Provider,
		&i.ProviderEventID,
		&i.SignatureValid,
		&i.BodySha256,
		&i.RawBody,
		&i.Headers,
		&i.Status,
		&i.ErrorCode,
		&i.ReceivedAt,
		&i.ProcessedAt,
		&i.RetainUntil,
	)
	return i, err
}

