const recountBulkOperation = `-- name: RecountBulkOperation :one
UPDATE bulk_operations b
SET succeeded_count = c.succeeded,
    failed_count = c.failed,
    skipped_count = c.skipped,
    status = CASE
      WHEN c.pending > 0 THEN b.status
      WHEN c.failed = c.total AND c.total > 0 THEN 'failed'
      ELSE 'completed'
    END,
    completed_at = CASE WHEN c.pending > 0 THEN NULL ELSE now() END,
    updated_at = now()
FROM (
  SELECT
    count(*)::integer AS total,
    count(*) FILTER (WHERE status = 'pending')::integer AS pending,
    count(*) FILTER (WHERE status = 'succeeded')::integer AS succeeded,
    count(*) FILTER (WHERE status = 'failed')::integer AS failed,
    count(*) FILTER (WHERE status = 'skipped')::integer AS skipped
  FROM bulk_operation_items WHERE operation_id = $1
) c
WHERE b.id = $1
RETURNING b.id, b.kind, b.status, b.requested_by, b.reason, b.parameters, b.total_count, b.succeeded_count, b.failed_count, b.skipped_count, b.idempotency_key, b.created_at, b.updated_at, b.completed_at
`

// Counters are recomputed from the items rather than incremented, so a retried
// worker cannot double-count an outcome it already recorded.
func (q *Queries) RecountBulkOperation(ctx context.Context, operationID pgtype.UUID) (BulkOperation, error) {
	row := q.db.QueryRow(ctx, recountBulkOperation, operationID)
	var i BulkOperation
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.Status,
		&i.RequestedBy,
		&i.Reason,
		&i.Parameters,
		&i.TotalCount,
		&i.SucceededCount,
		&i.FailedCount,
		&i.SkippedCount,
		&i.IdempotencyKey,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CompletedAt,
	)
	return i, err
}

