const upsertPaymentProviderSettings = `-- name: UpsertPaymentProviderSettings :one
INSERT INTO payment_provider_settings (
  provider, merchant_id, enabled, display_order,
  credentials_ciphertext, webhook_secret_ciphertext, updated_by
) VALUES (
  $1, $2, $3, $4,
  $5, $6, $7
)
ON CONFLICT (provider, merchant_id) DO UPDATE
SET enabled = EXCLUDED.enabled,
    display_order = EXCLUDED.display_order,
    credentials_ciphertext = COALESCE(
      EXCLUDED.credentials_ciphertext, payment_provider_settings.credentials_ciphertext
    ),
    webhook_secret_ciphertext = COALESCE(
      EXCLUDED.webhook_secret_ciphertext, payment_provider_settings.webhook_secret_ciphertext
    ),
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
RETURNING provider, merchant_id, enabled, display_order, credentials_ciphertext, webhook_secret_ciphertext, recurring_enabled, recurring_test_status, recurring_tested_at, connection_status, connection_checked_at, connection_error_code, webhook_status, webhook_last_event_at, webhook_last_error_code, created_at, updated_at, updated_by
`

type UpsertPaymentProviderSettingsParams struct {
	Provider                string      `json:"provider"`
	MerchantID              string      `json:"merchant_id"`
	Enabled                 bool        `json:"enabled"`
	DisplayOrder            int32       `json:"display_order"`
	CredentialsCiphertext   []byte      `json:"credentials_ciphertext"`
	WebhookSecretCiphertext []byte      `json:"webhook_secret_ciphertext"`
	UpdatedBy               pgtype.UUID `json:"updated_by"`
}

// Null ciphertexts mean "keep what is stored". Recurring is written through the
// separate capability-test statement below, never here, so a settings save can
// never quietly enable it without a passing test.
func (q *Queries) UpsertPaymentProviderSettings(ctx context.Context, arg UpsertPaymentProviderSettingsParams) (PaymentProviderSetting, error) {
	row := q.db.QueryRow(ctx, upsertPaymentProviderSettings,
		arg.Provider,
		arg.MerchantID,
		arg.Enabled,
		arg.DisplayOrder,
		arg.CredentialsCiphertext,
		arg.WebhookSecretCiphertext,
		arg.UpdatedBy,
	)
	var i PaymentProviderSetting
	err := row.Scan(
		&i.Provider,
		&i.MerchantID,
		&i.Enabled,
		&i.DisplayOrder,
		&i.CredentialsCiphertext,
		&i.WebhookSecretCiphertext,
		&i.RecurringEnabled,
		&i.RecurringTestStatus,
		&i.RecurringTestedAt,
		&i.ConnectionStatus,
		&i.ConnectionCheckedAt,
		&i.ConnectionErrorCode,
		&i.WebhookStatus,
		&i.WebhookLastEventAt,
		&i.WebhookLastErrorCode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}
